const out = [];
function walk(node, depth){
  node.children.forEach(c => {
    if (c.type === 'COMPONENT' || c.type === 'COMPONENT_SET') {
      out.push({page: figma.currentPage.name, name: c.name, id: c.id, key: c.key, type: c.type});
    }
    if ('children' in c) walk(c, depth+1);
  });
}
figma.root.children.forEach(p => {
  out.push({PAGE: p.name});
  const prev = figma.currentPage;
  // note: walk on any page works via direct node access
});
// Instead, walk all pages by direct children (we can't setCurrentPage per page easily, but children accessible)
function walkAll(node){
  if (node.type === 'PAGE') {
    out.push({PAGE: node.name});
    if (node.children) node.children.forEach(c => {
      if (c.type === 'COMPONENT' || c.type === 'COMPONENT_SET') out.push({name: c.name, id: c.id, key: c.key, type: c.type});
      walkDeep(c);
    });
  } else {
    walkDeep(node);
  }
}
function walkDeep(node){
  if ('children' in node) node.children.forEach(c => {
    if (c.type === 'COMPONENT' || c.type === 'COMPONENT_SET') out.push({name: c.name, id: c.id, key: c.key, type: c.type});
    if ('children' in c) walkDeep(c);
  });
}
figma.root.children.forEach(p => walkAll(p));
figma.notify('discovery done');
JSON.stringify(out);

