function setBtnText(instanceNode, label){
  function findText(n){
    if(n.type==='TEXT') return n;
    if(n.children) for(const c of n.children){const r=findText(c); if(r) return r;}
    return null;
  }
  const t=findText(instanceNode);
  if(t){ t.characters=label; return true;}
  return false;
}

