function field(sheetp,label,x,y,w,placeholder,isFocused,brandColor){
  addText(sheetp,label,x,y,12,'Medium',isFocused?C.brand:C.text2);
  const f=frameAt(sheetp,'Field',x,y+22,w,52,C.card,12);
  f.strokes=isFocused?[{type:'SOLID',color:brandColor}]:[{type:'SOLID',color:hex('#E6E8EB')}];
  f.strokeWeight=isFocused?2:1;
  addText(f,placeholder,16,16,15,'Regular',placeholder==='5412 7534 0089 2216'?C.text:C.text3);
  return f;
}
