function makeButton(parent,label,w){
  const f=figma.createFrame();f.name='Button_'+label;f.resize(w,54);f.fills=[{type:'SOLID',color:C.brand}];f.cornerRadius=14;
  const t=figma.createText();t.fontName={family:'Inter',style:'Semi Bold'};t.characters=label;t.fontSize=17;
  t.fills=[{type:'SOLID',color:hex('#FFFFFF')}];t.textAlignHorizontal='CENTER';t.resize(w,20);t.y=(54-20)/2;t.x=0;
  f.appendChild(t);parent.appendChild(f);return f;
}
