function nav(nodeId, destId, navigation){
  const n = figma.getNodeById(nodeId);
  if(!n) return {nodeId, ok:false, err:'node not found'};
  try {
    n.reactions = [{
      trigger: { type: 'ON_CLICK', delay: 0 },
      action: { type: 'NODE', destinationId: destId, navigation: navigation || 'NAVIGATE', transition: { type: 'DISSOLVE', duration: 200 } }
    }];
    return {nodeId, ok:true, label:n.name};
  } catch(e){ return {nodeId, ok:false, err:String(e)}; }
}

