// Verify reactions exist; fail loudly if any missing
const ws = figma.getNodeById('8:2');
await figma.setCurrentPageAsync(ws);
const checks = {
  '84:75':1,'84:81':1,'84:87':1,'84:129':1,'86:72':1,'86:75':1,
  '98:140':1,'98:172':1,'95:143':1,'89:89':1,'95:145':1
};
let missing=0; let detail=[];
for(const id in checks){
  const n=figma.getNodeById(id);
  const has=(n && n.reactions && n.reactions.length>0);
  if(!has){ missing++; detail.push(id+':'+(n?n.name:'MISSING')); }
}
if(missing>0){ throw new Error('Missing reactions on '+detail.join(',')); }
figma.notify('All '+Object.keys(checks).length+' reactions verified OK');

