function connect(srcId, destId){
  const n = figma.getNodeById(srcId);
  if(!n) throw new Error('src '+srcId+' not found');
  n.reactions = [{
    trigger: { type: 'ON_CLICK' },
    action: {
      type: 'NODE',
      destinationId: destId,
      navigation: 'NAVIGATE',
      transition: { type: 'DISSOLVE', duration: 200, easing: { type: 'EASE_IN_AND_OUT' } }
    }
  }];
  if(n.reactions.length!==1) throw new Error('set '+srcId+' failed');
}

